<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Theme\Application;

use RecursiveIteratorIterator;
use RecursiveDirectoryIterator;
use Psr\Http\Message\RequestInterface;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render\TemplateRenderInput;
use Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render\TemplateRenderUsecase;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateOutputFormat;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;

/**
 * Application service that wraps an HTML fragment inside a full themed page layout.
 *
 * Acts as the single integration point between driver controllers and the theming system.
 * Template resolution follows a two-stage strategy: first, the TemplateRenderUsecase is
 * consulted for a database-backed page template (tenant-specific or global) identified by the
 * code "page.{template}"; if no database template is found, a filesystem PHP-closure fallback
 * from the bundled 'corporate' theme directory is used instead. Static theme assets (CSS, JS,
 * images) are copied on demand from the source theme directory into the public/.assets/oidc/
 * folder so they are served by the web server without requiring a separate build step.
 * The assetsPath is resolved from application configuration at construction time to allow the
 * base URL to be overridden per environment.
 */
class DecorateHtml
{
    private const string FALLBACK_THEME = 'corporate';

    private readonly string $assetsPath;

    public function __construct(
        AppConfig $config,
        Context $context,
        private readonly TemplateRenderUsecase $renderer,
        private readonly TenantReadGateway $tenantGateway,
    ) {
        $this->assetsPath = $config->get('oidc.theme.path', $context->getBaseUrl() . '/');
    }

    /**
     * Wrap $innerContent in the full page layout for the given $template hint ('index' or 'full').
     *
     * Resolution order:
     *   1. DB template page.{template} resolved by TemplateRenderUsecase (tenant-specific → global).
     *   2. Filesystem PHP closure fallback from Themes/{fallback}/{template}.php.
     */
    public function getFullPage(
        RequestInterface $request,
        string $title,
        string $innerContent,
        string $locale,
        string $template = 'index',
        ?string $tenantDomain = null,
    ): string {
        $tenantRef = $this->resolveTenantRef($tenantDomain);
        $rendered = $this->renderer->render(new TemplateRenderInput(
            code: "page.{$template}",
            channel: TemplateChannelOptions::HTML,
            tenant: $tenantRef,
            variables: [
                'innerContent' => $innerContent,
                'title' => $title,
            ],
            outputFormat: TemplateOutputFormat::HTML,
            locale: $locale !== '' ? $locale : null,
        ))->rendered();

        if ($rendered !== null) {
            return $rendered->htmlContent();
        }

        return $this->filesystemFallback($template, $title, $innerContent, $locale);
    }

    private function resolveTenantRef(?string $tenantDomain): ?TenantRef
    {
        if ($tenantDomain === null) {
            return null;
        }
        $tenant = $this->tenantGateway->findOneByDomain($tenantDomain);

        return $tenant !== null ? new TenantRef($tenant->uid()) : null;
    }

    private function filesystemFallback(
        string $template,
        string $title,
        string $innerContent,
        string $locale,
    ): string {
        $srcDir    = __DIR__ . "/../Themes/" . self::FALLBACK_THEME . "/";
        $projectRoot = realpath(__DIR__ . '/../../../../../..');
        $publicPath = $projectRoot !== false ? $projectRoot . '/public' : __DIR__ . '/../../../../../../public';
        $targetDir = $publicPath . "/.assets/oidc/" . self::FALLBACK_THEME;
        $this->dumpTheme($srcDir, $targetDir);
        $theme = "{$this->assetsPath}.assets/oidc/" . self::FALLBACK_THEME;

        $layoutFile = $srcDir . "{$template}.php";
        if (!file_exists($layoutFile)) {
            return $innerContent;
        }

        $callback = require $layoutFile;

        return $callback($theme, $title, $innerContent, $locale);
    }

    private function dumpTheme(string $srcDir, string $targetDir): void
    {
        $allowedExtensions = ['html', 'js', 'css', 'png', 'jpg', 'jpeg', 'webp'];

        if (!is_dir($targetDir)) {
            mkdir($targetDir, 0777, true);
        }

        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($srcDir, RecursiveDirectoryIterator::SKIP_DOTS),
            RecursiveIteratorIterator::SELF_FIRST
        );

        foreach ($iterator as $item) {
            $relativePath = substr($item->getPathname(), strlen($srcDir));
            $destPath     = $targetDir . DIRECTORY_SEPARATOR . $relativePath;

            if ($item->isDir()) {
                if (!is_dir($destPath)) {
                    mkdir($destPath, 0777, true);
                }
            } else {
                $ext = pathinfo($item->getFilename(), PATHINFO_EXTENSION);
                if (in_array($ext, $allowedExtensions)) {
                    copy($item->getPathname(), $destPath);
                }
            }
        }
    }
}
